function compile(score) { return {score,timeline:{notes:score.parts.flatMap(p=>p.notes.filter(n=>n.pitch).map(n=>({id:n.id,part_id:p.id,midi:pitchMidi(n.pitch),start_ms:beat(n.at)*60000/score.tempo[0].bpm,duration_ms:beat(n.duration)*60000/score.tempo[0].bpm,voice:n.voice,staff:n.staff}))),duration_ms:1000*120/score.tempo[0].bpm},diagnostics:[]}; }
// A fixture endpoint models the documented backend contract; production JS never groups notes.
function mockTargetPlan({timeline,profile}) {
 const notes=[],groups=[];
 for(const source of timeline.notes){
  let index=profile.kind==='piano'?notes.findIndex(note=>note.start_ms===source.start_ms&&note.midi===source.midi):-1;
  const ids=source.source_note_ids?.length?source.source_note_ids:[source.source_note_id||source.id];
  if(index<0){index=notes.length;notes.push({...source,source_note_ids:[...ids]});groups.push({target_id:source.id,source_occurrence_ids:[source.id],source_note_ids:[...ids],part_ids:[source.part_id]})}
  else{notes[index].duration_ms=Math.max(notes[index].duration_ms,source.duration_ms);notes[index].source_note_ids.push(...ids);groups[index].source_occurrence_ids.push(source.id);groups[index].source_note_ids.push(...ids);groups[index].part_ids=[...new Set([...groups[index].part_ids,source.part_id])]}
 }
 return{timeline:{...timeline,notes},groups,diagnostics:[],source_note_count:timeline.notes.length,target_count:notes.length,playable:notes.length>0};
}
