test('rendered dark secondary text meets AA, uses readable sizes, and notation fits its panel',async()=>{
 await page.locator('#theme-mode').selectOption('dark');const checks=await page.evaluate(async()=>{const{contrastRatio}=await import('/themes.js');const hex=color=>{const values=color.match(/[\d.]+/g).slice(0,3).map(Number);return'#'+values.map(v=>Math.round(v).toString(16).padStart(2,'0')).join('')};return['.topbar p','.catalog-item small','#score-meta','.notation-note','#practice-hint','.feedback-intro p','.practice-options summary','.library-foot'].map(selector=>{const el=document.querySelector(selector);let owner=el;let bg;while(owner){bg=getComputedStyle(owner).backgroundColor;if(bg!=='rgba(0, 0, 0, 0)'&&bg!=='transparent')break;owner=owner.parentElement}return{selector,ratio:contrastRatio(hex(getComputedStyle(el).color),hex(bg)),size:parseFloat(getComputedStyle(el).fontSize)}})});for(const check of checks){assert.ok(check.ratio>=4.5,JSON.stringify(check));assert.ok(check.size>=12,JSON.stringify(check))}
 for(const width of [1440,900,390]){await page.setViewportSize({width,height:900});await page.waitForTimeout(80);const box=await page.locator('#notation').evaluate(el=>({scroll:el.scrollWidth,client:el.clientWidth}));assert.ok(box.scroll<=box.client+1,JSON.stringify({width,...box}));}
});
