test('closing pending numbered-text export aborts preparation without a surprise download',async()=>{
 let release;const pending=new Promise(resolve=>release=resolve);let downloads=0;page.on('download',()=>downloads++);
 await page.route('**/api/export/jianpu',async route=>{await pending;await route.fulfill({contentType:'application/json',body:JSON.stringify({text:'1 3',diagnostics:[],note_map:['c4','e4']})}).catch(()=>{})});const request=page.waitForRequest('**/api/export/jianpu');await page.locator('#export-jianpu').click();await request;await page.locator('#jianpu-export-cancel').click();release();await page.waitForTimeout(60);assert.equal(await page.locator('#jianpu-export').isVisible(),false);assert.equal(downloads,0);assert.equal(await page.locator('#play-button').isEnabled(),true);
});
test('saved-library current card follows a pending score replacement and clears the old copy label',async()=>{
 const replacement={...structuredClone(fixture),id:'replacement',title:'Newly loaded score'};let release;const pending=new Promise(resolve=>release=resolve);
 await page.route('**/api/compile',async route=>{const score=route.request().postDataJSON();if(score.id==='replacement')await pending;await route.fulfill({contentType:'application/json',body:JSON.stringify(compile(score))})});
 const request=page.waitForRequest(req=>req.url().endsWith('/api/compile')&&req.postDataJSON().id==='replacement');await page.locator('#score-file').setInputFiles({name:'replacement.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(replacement))});await request;
 await page.locator('#library-button').click();await page.waitForFunction(()=>document.querySelector('#library-status').textContent.startsWith('Ready.'));assert.equal(await page.locator('#library-current-title').textContent(),fixture.title);await page.locator('#library-label').fill('Label for the previous score');release();
 await page.waitForFunction(()=>document.querySelector('#library-current-title').textContent==='Newly loaded score');assert.equal(await page.locator('#library-label').inputValue(),'');assert.match(await page.locator('#library-status').textContent(),/Current score changed/);
 await page.locator('#library-save-copy').click();await page.waitForFunction(()=>document.querySelectorAll('#library-list>li').length===1);assert.equal(await page.locator('#library-list strong').textContent(),replacement.title);
 const promise=page.waitForEvent('download');await page.locator('[data-library-export]').click();assert.deepEqual(JSON.parse(await readFile(await(await promise).path(),'utf8')),replacement);
});
